package lint

import (
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"

	"github.com/tim-chaplin/fab-deck-optimizer/internal/registry"
	"gopkg.in/yaml.v3"
)

// Tests that every implemented card variant is in the registry. cardsByID is generated by
// cardgen from internal/card/cards/*.yaml; a generated file left stale after a card was
// added would silently drop that card from every deck the optimiser builds. This fails
// when internal/registry/cards_gen.go is out of date — run `go generate ./...`.
func TestRegistry_CoversEveryImplementedCard(t *testing.T) {
	cardsDir := filepath.Join(RepoRoot(t), "internal", "card", "cards")
	entries, err := os.ReadDir(cardsDir)
	if err != nil {
		t.Fatalf("read cards dir: %v", err)
	}

	implemented := map[string]bool{}
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".yaml") {
			continue
		}
		data, err := os.ReadFile(filepath.Join(cardsDir, e.Name()))
		if err != nil {
			t.Fatalf("read %s: %v", e.Name(), err)
		}
		var g struct {
			Variants []struct {
				ID string `yaml:"id"`
			} `yaml:"variants"`
		}
		if err := yaml.Unmarshal(data, &g); err != nil {
			t.Fatalf("parse %s: %v", e.Name(), err)
		}
		for _, v := range g.Variants {
			implemented[v.ID] = true
		}
	}

	registered := map[string]bool{}
	for _, id := range registry.AllCards() {
		registered[reflect.TypeOf(registry.GetCard(id)).Name()] = true
	}

	for id := range implemented {
		if !registered[id] {
			t.Errorf("%s is implemented but not registered — run `go generate ./...`", id)
		}
	}
	for id := range registered {
		if !implemented[id] {
			t.Errorf("%s is registered but has no card yaml — internal/registry/cards_gen.go is stale", id)
		}
	}
}
